INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6800, 'up-to-date', 'ʌp tə ˈdeɪt', 'adjective', '{"zh-TW":["最新的；及時更新的","符合現代的"],"en":["incorporating latest information","current"]}', NULL, 'up-to-date report/up-to-date records', '[{"en":"Please keep your records up to date.","zh-TW":"請保持記錄最新。"}]', '{"adverb":"up to date"}', NULL, 4, 6800, NULL),
(6801, 'upcycling', '/ˈʌpsaɪklɪŋ/', 'noun', '{"zh-TW":["升級再造；升級回收"],"en":["converting waste into something of higher value"]}', NULL, 'upcycling project / practice upcycling', '[{"en":"Upcycling old furniture reduces waste and saves money.","zh-TW":"升級再造舊家具可減少浪費並節省費用。"},{"en":"The brand is known for upcycling discarded materials into fashionable products.","zh-TW":"該品牌以將廢棄材料升級再造成時尚產品而聞名。"}]', '{"verb":"upcycle"}', NULL, 3, 6801, NULL),
(6802, 'update', '/ʌpˈdeɪt/', 'noun, verb', '{"zh-TW":["更新；最新資訊","更新"],"en":["new information; a newer version","to bring up to date"]}', NULL, 'software update / provide an update / update regularly', '[{"en":"Please update the spreadsheet with the latest data.","zh-TW":"請用最新數據更新試算表。"},{"en":"I''ll provide a weekly status update.","zh-TW":"我會提供每週的進度更新。"}]', '{"noun":"update","verb":"update"}', NULL, 2, 6802, 235),
(6803, 'upfront payment', '/ˈʌpfrʌnt ˈpeɪmənt/', 'noun', '{"zh-TW":["預付款；前期付款"],"en":["a payment made at the beginning of a transaction or contract"]}', NULL, 'require an upfront payment / upfront payment terms', '[{"en":"An upfront payment of 30% was required before production started.","zh-TW":"在開始生產之前需要30%的預付款。"},{"en":"Freelancers often request an upfront payment to secure new projects.","zh-TW":"自由工作者通常要求預付款以確保新項目。"}]', '{"synonym":"advance payment","opposite":"deferred payment"}', NULL, 5, 6803, NULL),
(6804, 'upgrade', '/ʌpˈɡreɪd/', 'noun, verb', '{"zh-TW":["升級","升級"],"en":["an improvement; a higher version","to raise to a higher standard"]}', NULL, 'system upgrade / upgrade to / free upgrade', '[{"en":"We upgraded our servers last month.","zh-TW":"上個月我們升級了伺服器。"},{"en":"Customers can upgrade to the premium plan.","zh-TW":"客戶可以升級到高級方案。"}]', '{"noun":"upgrade","verb":"upgrade"}', NULL, 3, 6804, NULL),
(6805, 'uphold', '/ʌpˈhoʊld/', 'verb', '{"zh-TW":["維護；支持"],"en":["to maintain or defend a principle"]}', NULL, 'uphold standards / uphold the law / uphold a decision', '[{"en":"The court upheld the original ruling.","zh-TW":"法院維持了原判。"},{"en":"We uphold the highest ethical standards.","zh-TW":"我們堅持最高的道德標準。"}]', '{"verb":"uphold"}', NULL, 2, 6805, NULL),
(6806, 'upload', '/ˈʌploʊd/', 'verb', '{"zh-TW":["上傳"],"en":["to transfer data to a remote system"]}', NULL, 'upload a file / upload speed', '[{"en":"Upload your resume to the website.","zh-TW":"將你的履歷上傳到網站。"},{"en":"The upload speed is too slow.","zh-TW":"上傳速度太慢了。"}]', '{"noun":"upload"}', NULL, 2, 6806, NULL),
(6807, 'upper', '/ˈʌpər/', 'adjective', '{"zh-TW":["上方的；較高的"],"en":["higher in position or rank"]}', NULL, 'upper management / upper limit / upper level', '[{"en":"Upper management approved the proposal.","zh-TW":"高層管理階層批准了提案。"},{"en":"The upper limit of the budget is $500,000.","zh-TW":"預算的上限是五十萬美元。"}]', '{"adjective":"upper","noun":"upper"}', NULL, 2, 6807, NULL),
(6808, 'upscale', '/ˈʌpskeɪl/', 'adjective', '{"zh-TW":["高檔的；高級的"],"en":["relating to affluent consumers; luxurious"]}', NULL, 'upscale market / upscale brand / upscale restaurant', '[{"en":"The brand targets the upscale market segment.","zh-TW":"該品牌瞄準高端市場區隔。"},{"en":"They opened an upscale restaurant downtown.","zh-TW":"他們在市中心開了一家高級餐廳。"}]', '{"adjective":"upscale"}', NULL, 3, 6808, NULL),
(6809, 'upsell', '/ˈʌpsɛl/', 'verb', '{"zh-TW":["向上銷售；追加銷售"],"en":["to persuade a customer to buy a more expensive product"]}', NULL, 'upsell a customer / upsell opportunity', '[{"en":"Train staff to upsell premium options to customers.","zh-TW":"培訓員工向顧客追加銷售高級選項。"},{"en":"The upsell strategy increased average transaction value.","zh-TW":"追加銷售策略提高了平均交易金額。"}]', '{"noun":"upsell","adjective":"upsold"}', NULL, 2, 6809, NULL),
(6810, 'upselling', '/ˈʌpselɪŋ/', 'noun', '{"zh-TW":["向上銷售；升級銷售"],"en":["encouraging customers to purchase a more expensive version of a product"]}', NULL, 'upselling technique / upselling opportunity / practice upselling', '[{"en":"The waiter used upselling to suggest premium dishes.","zh-TW":"服務員使用向上銷售技巧推薦高檔菜肴。"},{"en":"Upselling increased average transaction value by 20%.","zh-TW":"向上銷售使平均交易金額增加了20%。"}]', '{"verb":"upsell"}', NULL, 3, 6810, NULL),
(6811, 'upselling technique', '/ˈʌpselɪŋ tekˈniːk/', 'noun', '{"zh-TW":["追加銷售技巧"],"en":["a sales method persuading customers to purchase a higher-end product"]}', NULL, 'apply upselling techniques / effective upselling technique', '[{"en":"Training staff in upselling techniques increased average order values by 18%.","zh-TW":"培訓員工掌握追加銷售技巧使平均訂單金額增加了18%。"},{"en":"An effective upselling technique focuses on customer benefits, not price.","zh-TW":"有效的追加銷售技巧側重於客戶效益而非價格。"}]', NULL, NULL, 5, 6811, NULL),
(6812, 'upskill', '/ˌʌpˈskɪl/', 'verb', '{"zh-TW":["提升技能；再培訓"],"en":["to learn new skills or teach workers new skills to improve competence"]}', NULL, 'upskill employees / upskill the workforce', '[{"en":"The company invested in upskilling employees in digital tools.","zh-TW":"公司投資於提升員工在數位工具方面的技能。"},{"en":"Upskilling reduces the need for external hiring.","zh-TW":"提升技能減少了對外部招聘的需求。"}]', '{"noun":"upskilling"}', NULL, 3, 6812, NULL),
(6813, 'upstream', '/ˈʌpstriːm/', 'adjective', '{"zh-TW":["上游的"],"en":["relating to the early stages of production or supply chain activities"]}', NULL, 'upstream supplier / upstream process / upstream operations', '[{"en":"Upstream operations include raw material sourcing and primary processing.","zh-TW":"上游運營包括原材料採購和初級加工。"},{"en":"A disruption at an upstream supplier can halt the entire production line.","zh-TW":"上游供應商的中斷可能導致整條生產線停工。"}]', '{"opposite":"downstream"}', NULL, 3, 6813, NULL),
(6814, 'upsurge', '/ˈʌpsɜːrdʒ/', 'noun', '{"zh-TW":["激增；猛漲"],"en":["a sudden large increase in something"]}', NULL, 'upsurge in demand / upsurge in sales', '[{"en":"An upsurge in online shopping boosted warehouse capacity needs.","zh-TW":"線上購物的激增提高了對倉庫容量的需求。"},{"en":"The upsurge in raw material costs squeezed profit margins.","zh-TW":"原材料成本的猛漲壓縮了利潤率。"}]', '{"verb":"upsurge"}', NULL, 3, 6814, NULL),
(6815, 'uptime', '/ˈʌptaɪm/', 'noun', '{"zh-TW":["正常運行時間"],"en":["the period during which a system is fully operational"]}', NULL, 'system uptime / guaranteed uptime / 99.9% uptime / maximize uptime', '[{"en":"The provider guarantees 99.9% uptime under the SLA.","zh-TW":"提供商在服務水準協議下保證99.9%的正常運行時間。"},{"en":"High uptime is critical for e-commerce businesses.","zh-TW":"高正常運行時間對電子商務業務至關重要。"}]', '{"antonym":"downtime"}', NULL, 2, 6815, NULL),
(6816, 'urban', '/ˈɜːrbən/', 'adjective', '{"zh-TW":["都市的；城市的"],"en":["relating to a city or town"]}', NULL, 'urban area / urban development / urban planning', '[{"en":"Urban areas face unique transportation challenges.","zh-TW":"都市地區面臨獨特的交通挑戰。"},{"en":"The company focuses on urban development projects.","zh-TW":"公司專注於都市開發案。"}]', '{"noun":"urbanization","adjective":"urban","verb":"urbanize"}', NULL, 2, 6816, NULL),
(6817, 'urban renewal', '/''ɜːrbən rɪˌnjuːəl/', 'noun', '{"zh-TW":["城市更新；都市更新"],"en":["the redevelopment of run-down urban areas to improve conditions and attract investment"]}', NULL, 'support urban renewal / urban renewal project / urban renewal program', '[{"en":"The urban renewal project transformed a neglected neighborhood into a vibrant community.","zh-TW":"城市更新項目將一個被忽視的社區改造成了充滿活力的社區。"},{"en":"Urban renewal often displaces existing residents, raising concerns about gentrification.","zh-TW":"城市更新常常使現有居民流離失所，引發士紳化的擔憂。"}]', NULL, NULL, 5, 6817, NULL),
(6818, 'urban sprawl', '/''ɜːrbən sprɔːl/', 'noun', '{"zh-TW":["城市蔓延；都市擴張"],"en":["the uncontrolled expansion of urban areas into rural land"]}', NULL, 'manage urban sprawl / combat urban sprawl / effects of urban sprawl', '[{"en":"Urban sprawl leads to increased reliance on cars and longer commute times.","zh-TW":"城市蔓延導致對汽車的依賴增加和通勤時間延長。"},{"en":"City planners are working to manage urban sprawl by promoting higher-density housing.","zh-TW":"城市規劃者正在通過推動較高密度住宅來管理城市蔓延。"}]', NULL, NULL, 4, 6818, NULL),
(6819, 'urbanization', '/ˌɜːrbənɪˈzeɪʃən/', 'noun', '{"zh-TW":["都市化；城市化"],"en":["the process by which more people come to live in towns and cities"]}', NULL, 'rapid urbanization / urbanization rate / urbanization trend', '[{"en":"Rapid urbanization has created demand for affordable housing and public transport.","zh-TW":"快速的都市化創造了對可負擔住房和公共交通的需求。"},{"en":"Urbanization in developing countries often outpaces infrastructure development.","zh-TW":"發展中國家的都市化往往超過基礎設施發展的速度。"}]', '{"verb":"urbanize","adjective":"urbanized"}', NULL, 4, 6819, NULL),
(6820, 'urge', '/ɜːrdʒ/', 'verb, noun', '{"zh-TW":["敦促；催促","衝動"],"en":["to strongly encourage","a strong desire"]}', NULL, 'urge caution / strongly urge / urge someone to', '[{"en":"The board urged management to cut costs.","zh-TW":"董事會敦促管理層削減成本。"},{"en":"Experts urge companies to adopt sustainable practices.","zh-TW":"專家敦促企業採用永續做法。"}]', '{"noun":"urge, urgency","verb":"urge","adjective":"urgent"}', NULL, 1, 6820, NULL),
(6821, 'urgent', '/ˈɜːrdʒənt/', 'adjective', '{"zh-TW":["緊急的；迫切的"],"en":["requiring immediate action"]}', NULL, 'urgent matter / urgent need / urgent request', '[{"en":"This is an urgent matter that requires your attention.","zh-TW":"這是一個需要你注意的緊急事務。"},{"en":"There is an urgent need for additional funding.","zh-TW":"迫切需要額外的資金。"}]', '{"noun":"urgency","adjective":"urgent","adverb":"urgently"}', NULL, 2, 6821, NULL),
(6822, 'urgent care', '/ˈɜːrdʒənt kɛər/', 'noun', '{"zh-TW":["緊急醫療護理"],"en":["immediate medical care for non-life-threatening conditions"]}', NULL, 'urgent care center / visit urgent care', '[{"en":"Go to urgent care for minor injuries or illnesses.","zh-TW":"輕傷或小病請前往緊急醫療護理中心就診。"},{"en":"Urgent care is faster than the emergency room for minor issues.","zh-TW":"對於小問題，緊急醫療護理比急診室更快。"}]', NULL, NULL, 4, 6822, NULL),
(6823, 'urologist', '/jʊˈrɒlədʒɪst/', 'noun', '{"zh-TW":["泌尿科醫師"],"en":["a physician specializing in the urinary system and male reproductive system"]}', NULL, 'consult a urologist / qualified urologist / urologist referral', '[{"en":"The urologist performed surgery to remove the kidney stone.","zh-TW":"泌尿科醫師進行手術取出腎結石。"},{"en":"Prostate health issues are commonly managed by a urologist.","zh-TW":"前列腺健康問題通常由泌尿科醫師管理。"}]', NULL, NULL, 3, 6823, NULL),
(6824, 'usage', '/ˈjuːsɪdʒ/', 'noun', '{"zh-TW":["使用；用法"],"en":["the way something is used; the amount used"]}', NULL, 'energy usage / data usage / proper usage', '[{"en":"Monitor your data usage to avoid extra charges.","zh-TW":"監控您的數據使用量以避免額外費用。"},{"en":"Electricity usage peaks during summer months.","zh-TW":"用電量在夏季月份達到高峰。"}]', '{"noun":"usage, use","verb":"use"}', NULL, 2, 6824, NULL),
(6825, 'use', 'juːz', 'verb', '{"zh-TW":["使用；利用","消耗"],"en":["to employ for a purpose","to consume"]}', NULL, 'use a tool/resource', '[{"en":"Please use the official form.","zh-TW":"請使用官方表格。"}]', '{"noun":"use, user","adjective":"useful, useless","adverb":"usefully"}', NULL, 1, 6825, NULL),
(6826, 'user acceptance testing', '/ˈjuːzər əkˈseptəns ˈtestɪŋ/', 'noun', '{"zh-TW":["用戶驗收測試"],"en":["testing conducted by end users to verify a system meets requirements"]}', NULL, 'conduct UAT / pass user acceptance testing / UAT sign-off', '[{"en":"User acceptance testing uncovered several usability issues.","zh-TW":"用戶驗收測試發現了幾個可用性問題。"},{"en":"The product cannot go live until it passes user acceptance testing.","zh-TW":"產品在通過用戶驗收測試之前不能上線。"}]', '{"abbreviation":"UAT"}', NULL, 5, 6826, NULL),
(6827, 'user account', '/ˈjuːzər əˈkaʊnt/', 'noun', '{"zh-TW":["使用者帳號"],"en":["a personal account providing access to a system"]}', NULL, 'create a user account / manage user accounts', '[{"en":"Create a user account to access the platform.","zh-TW":"建立使用者帳號以訪問平台。"},{"en":"The system administrator manages all user accounts.","zh-TW":"系統管理員管理所有使用者帳號。"}]', NULL, NULL, 4, 6827, NULL),
(6828, 'user experience', '/ˌjuːzər ɪkˈspɪəriəns/', 'noun', '{"zh-TW":["使用者體驗"],"en":["the overall experience of a person using a product or service"]}', NULL, 'improve user experience / positive user experience / design for UX', '[{"en":"A smooth user experience keeps customers coming back.","zh-TW":"流暢的使用者體驗讓客戶持續回訪。"},{"en":"The app was redesigned based on user experience research.","zh-TW":"應用程式根據使用者體驗研究重新設計了。"}]', '{"abbreviation":"UX"}', NULL, 5, 6828, NULL),
(6829, 'user interface', '/ˈjuːzər ˈɪntərfeɪs/', 'noun', '{"zh-TW":["使用者介面"],"en":["the visual design and controls through which users interact with a system"]}', NULL, 'intuitive user interface / design the user interface / improve the UI', '[{"en":"A clean user interface reduces the learning curve for new users.","zh-TW":"簡潔的使用者介面降低了新用戶的學習曲線。"},{"en":"The redesigned user interface improved customer satisfaction scores.","zh-TW":"重新設計的使用者介面提高了客戶滿意度分數。"}]', '{"abbreviation":"UI"}', NULL, 5, 6829, NULL),
(6830, 'user story', '/ˈjuːzər ˈstɔːri/', 'noun', '{"zh-TW":["用戶故事"],"en":["a short description of a feature from an end user''s perspective"]}', NULL, 'write user stories / user story format / prioritize user stories', '[{"en":"Each user story describes what a specific type of user wants to accomplish.","zh-TW":"每個用戶故事描述了特定類型用戶想要完成的事情。"},{"en":"The product team wrote 50 user stories for the new release.","zh-TW":"產品團隊為新版本編寫了50個用戶故事。"}]', '{"plural":"user stories"}', NULL, 4, 6830, NULL),
(6831, 'usual', 'ˈjuːʒuəl', 'adjective', '{"zh-TW":["通常的；平常的","習慣的"],"en":["happening regularly","normal"]}', NULL, 'as usual/usual procedure', '[{"en":"Follow the usual procedure for approvals.","zh-TW":"遵循通常的審批程序。"}]', '{"adverb":"usually"}', NULL, 2, 6831, NULL),
(6832, 'utilitarian', '/ˌjuːtɪlɪˈteəriən/', 'adjective', '{"zh-TW":["功利主義的；實用的"],"en":["designed to be useful rather than attractive; relating to utilitarianism"]}', NULL, 'utilitarian design / utilitarian approach / utilitarian philosophy', '[{"en":"Utilitarian architecture prioritizes function and efficiency over aesthetic appeal.","zh-TW":"功利主義建築優先考慮功能和效率，而非美學吸引力。"},{"en":"The utilitarian view holds that actions are right if they maximize overall well-being.","zh-TW":"功利主義觀點認為，如果行動能最大化整體福祉，則是正確的。"}]', '{"noun":"utilitarianism","adverb":"utilitarianly"}', NULL, 4, 6832, NULL),
(6833, 'utilitarianism', '/juːˌtɪlɪˈteəriənɪzəm/', 'noun', '{"zh-TW":["功利主義"],"en":["the ethical theory that the best action maximizes overall happiness"]}', NULL, 'apply utilitarianism / principle of utilitarianism / critique of utilitarianism', '[{"en":"Utilitarianism judges actions by their consequences for overall welfare.","zh-TW":"功利主義通過行動對整體福利的後果來判斷行動。"},{"en":"Critics argue that utilitarianism can justify harming minorities for majority benefit.","zh-TW":"批評者認為功利主義可以為了多數人的利益而傷害少數群體。"}]', '{"adjective":"utilitarian","noun2":"utilitarian"}', NULL, 5, 6833, NULL),
(6834, 'utility', '/juːˈtɪləti/', 'noun', '{"zh-TW":["公用事業；效用"],"en":["a service such as electricity or water; usefulness"]}', NULL, 'utility bills / utility company / practical utility', '[{"en":"Utility bills have increased this year.","zh-TW":"今年公用事業費用增加了。"},{"en":"The software has great practical utility.","zh-TW":"這個軟體有很高的實用性。"}]', '{"noun":"utility","adjective":"utilitarian"}', NULL, 3, 6834, NULL),
(6835, 'utility cost', '/juːˈtɪlɪti kɒst/', 'noun', '{"zh-TW":["水電費；公用事業費用"],"en":["the cost of electricity, gas, water, and other public services"]}', NULL, 'reduce utility costs / utility cost management', '[{"en":"Energy efficiency measures reduced utility costs by 15%.","zh-TW":"能源效率措施將水電費降低了15%。"},{"en":"Utility costs are included in the monthly fixed overhead.","zh-TW":"水電費包含在每月固定間接費用中。"}]', NULL, NULL, 4, 6835, NULL),
(6836, 'utility maximization', '/juːˈtɪlɪti ˌmæksɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["效用最大化"],"en":["the economic assumption that individuals act to maximize their personal satisfaction or utility"]}', NULL, 'assume utility maximization / utility maximization theory / beyond utility maximization', '[{"en":"Classical economics assumes that consumers make decisions based on utility maximization.","zh-TW":"古典經濟學假設消費者根據效用最大化做出決策。"},{"en":"Behavioral economics challenges the utility maximization assumption by highlighting irrational choices.","zh-TW":"行為經濟學通過強調非理性選擇來挑戰效用最大化假設。"}]', NULL, NULL, 5, 6836, NULL),
(6837, 'utilization', '/ˌjuːtɪlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["利用率；使用率"],"en":["the percentage of available capacity that is actually being used"]}', NULL, 'resource utilization / server utilization / high utilization rate', '[{"en":"High staff utilization can lead to burnout without proper management.","zh-TW":"在沒有適當管理的情況下，高員工利用率可能導致倦怠。"},{"en":"The report showed server utilization was consistently above 90%.","zh-TW":"報告顯示伺服器利用率持續高於90%。"}]', '{"verb":"utilize","adjective":"utilized"}', NULL, 4, 6837, 812),
(6838, 'utilize', '/ˈjuːtəlaɪz/', 'verb', '{"zh-TW":["利用；使用"],"en":["to make practical use of"]}', NULL, 'utilize resources / fully utilize / utilize technology', '[{"en":"We should utilize all available resources.","zh-TW":"我們應該利用所有可用資源。"},{"en":"The team utilized new software to improve efficiency.","zh-TW":"團隊利用新軟體提高效率。"}]', '{"noun":"utilization","verb":"utilize"}', NULL, 3, 6838, 236),
(6839, 'vacancy', '/ˈveɪkənsi/', 'noun', '{"zh-TW":["空缺；職缺"],"en":["an unoccupied position or space"]}', NULL, 'job vacancy / fill a vacancy / vacancy rate', '[{"en":"There are several vacancies in the IT department.","zh-TW":"IT部門有幾個職缺。"},{"en":"The hotel vacancy rate dropped during the holiday.","zh-TW":"假期期間飯店空房率下降。"}]', '{"noun":"vacancy","adjective":"vacant"}', NULL, 3, 6839, 476),
(6840, 'vacancy rate', '/ˈveɪkənsi reɪt/', 'noun', '{"zh-TW":["空置率"],"en":["the percentage of unoccupied units in a building or market"]}', NULL, 'high vacancy rate / reduce the vacancy rate', '[{"en":"A high vacancy rate indicates weak demand in the market.","zh-TW":"高空置率表明市場需求疲軟。"},{"en":"The building''s vacancy rate dropped to 3% this year.","zh-TW":"今年大樓的空置率降至3%。"}]', NULL, NULL, 4, 6840, NULL),
(6841, 'vacant', '/ˈveɪkənt/', 'adjective', '{"zh-TW":["空的；空缺的"],"en":["not occupied; empty"]}', NULL, 'vacant position / vacant lot / vacant office', '[{"en":"The position has been vacant for three months.","zh-TW":"這個職位已經空缺三個月了。"},{"en":"Several offices remain vacant in the building.","zh-TW":"大樓中有幾間辦公室仍然空著。"}]', '{"noun":"vacancy","adjective":"vacant","verb":"vacate"}', NULL, 2, 6841, NULL),
(6842, 'vacant land', '/''veɪkənt lænd/', 'noun', '{"zh-TW":["空地；閒置土地"],"en":["land that has no existing structures and is available for development or sale"]}', NULL, 'purchase vacant land / develop vacant land / vacant land zoning', '[{"en":"The company purchased vacant land near the city to build a new distribution center.","zh-TW":"公司在城市附近購買了空地，建設新的配送中心。"},{"en":"Vacant land in prime locations can be an excellent investment opportunity.","zh-TW":"黃金地段的空地可以是絕佳的投資機會。"}]', NULL, NULL, 4, 6842, NULL),
(6843, 'vacant property', '/''veɪkənt ˌprɒpərti/', 'noun', '{"zh-TW":["空置房產；空屋"],"en":["a property that is empty and not currently occupied by any tenant or owner"]}', NULL, 'purchase a vacant property / renovate a vacant property / vacant property tax', '[{"en":"The city introduced a tax on vacant property to encourage owners to rent or sell.","zh-TW":"市政府對空置房產徵收稅費，鼓勵業主出租或出售。"},{"en":"Vacant properties in prime locations can attract significant investor interest.","zh-TW":"黃金地段的空置房產可以吸引大量投資者興趣。"}]', NULL, NULL, 5, 6843, NULL),
(6844, 'vaccination', '/ˌvæksɪˈneɪʃən/', 'noun', '{"zh-TW":["接種疫苗；疫苗接種"],"en":["the process of administering a vaccine to protect against disease"]}', NULL, 'receive vaccination / mass vaccination / childhood vaccination', '[{"en":"Vaccination programs have eliminated many once-deadly diseases.","zh-TW":"疫苗接種計畫消除了許多曾經致命的疾病。"},{"en":"Annual influenza vaccination is recommended for elderly populations.","zh-TW":"建議老年人口每年接種流感疫苗。"}]', '{"verb":"vaccinate","noun2":"vaccine"}', NULL, 4, 6844, NULL),
(6845, 'vaccine', '/ˈvæksiːn/', 'noun', '{"zh-TW":["疫苗"],"en":["a substance used to stimulate immunity to a disease"]}', NULL, 'flu vaccine / receive a vaccine', '[{"en":"The flu vaccine is recommended every autumn.","zh-TW":"建議每年秋天接種流感疫苗。"},{"en":"The vaccine has been approved for use in adults.","zh-TW":"該疫苗已獲准用於成人。"}]', '{"verb":"vaccinate","noun":"vaccination"}', NULL, 3, 6845, NULL),
(6846, 'vague', '/''veɪɡ/', 'adjective', '{"zh-TW":["模糊的；不清楚的"],"en":["of uncertain, indefinite, or unclear character or meaning"]}', NULL, 'vague instructions / vague answer / vague idea', '[{"en":"Her vague instructions left the team confused about what they were supposed to do.","zh-TW":"她模糊的指示讓團隊對應該做什麼感到困惑。"},{"en":"He gave only a vague description of the problem, making it difficult to find a solution.","zh-TW":"他只給出了問題的模糊描述，使得找到解決方案變得困難。"}]', '{"adverb":"vaguely","noun":"vagueness"}', NULL, 2, 6846, NULL),
(6847, 'valet', '/''væleɪ/', 'noun', '{"zh-TW":["泊車服務員；男僕"],"en":["a person who parks cars for hotel or restaurant guests; also a personal servant"]}', NULL, 'valet parking / hand keys to the valet / valet service', '[{"en":"He handed his car keys to the valet upon arriving at the hotel.","zh-TW":"他到達飯店後把車鑰匙交給了泊車服務員。"},{"en":"The valet brought the car around within five minutes of the guest''s request.","zh-TW":"在客人要求後，泊車服務員在五分鐘內將車開了過來。"}]', NULL, NULL, 2, 6847, NULL),
(6848, 'valet parking', '/ˈvæleɪ ˈpɑːrkɪŋ/', 'noun', '{"zh-TW":["代客泊車"],"en":["a service where an attendant parks your car"]}', NULL, 'use valet parking / valet parking fee', '[{"en":"The hotel offers complimentary valet parking.","zh-TW":"飯店提供免費代客泊車服務。"},{"en":"Hand your keys to the valet parking attendant.","zh-TW":"請將鑰匙交給代客泊車服務員。"}]', NULL, NULL, 5, 6848, NULL),
(6849, 'valid', '/ˈvælɪd/', 'adjective', '{"zh-TW":["有效的；正當的","有效的；合理的"],"en":["legally or logically acceptable","legally acceptable; logically sound"]}', '{"root":{"text":"val","meaning":"strong/worth (有力/有價值)"},"suffix":{"text":"-id","meaning":"being (…的)"},"logic":"有力量支撐的，即「有效的」。"}', 'valid passport / valid argument / valid reason; valid passport / valid point / valid until', '[{"en":"Your passport must be valid for at least six months.","zh-TW":"你的護照必須至少還有六個月效期。"},{"en":"That is a valid argument.","zh-TW":"那是一個正當的論點。"},{"en":"The coupon is valid until December 31.","zh-TW":"優惠券有效期至12月31日。"},{"en":"That''s a valid concern we should address.","zh-TW":"那是一個我們應該處理的合理顧慮。"}]', '{"noun":"validity","verb":"validate","adjective":"valid, invalid"}', NULL, 2, 6849, 477);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6850, 'validate', '/ˈvælɪdeɪt/', 'verb', '{"zh-TW":["驗證；確認有效"],"en":["to confirm the accuracy or validity of"]}', NULL, 'validate data / validate results / validate a claim', '[{"en":"The research validates our initial findings.","zh-TW":"研究驗證了我們最初的發現。"},{"en":"Please validate your parking ticket at reception.","zh-TW":"請在櫃台驗證您的停車票。"}]', '{"noun":"validation, validity","verb":"validate","adjective":"valid"}', NULL, 3, 6850, 725),
(6851, 'validation', 'ˌvælɪˈdeɪʃən', 'noun', '{"zh-TW":["驗證；確認","有效確認"],"en":["confirmation of correctness","official approval"]}', NULL, 'data validation/external validation', '[{"en":"Validation of all forms is required.","zh-TW":"所有表格都需要驗證。"}]', '{"verb":"validate","adjective":"valid, validated"}', NULL, 4, 6851, NULL),
(6852, 'validity', '/vəˈlɪdɪti/', 'noun', '{"zh-TW":["有效性；正確性"],"en":["the quality of being logically or factually sound"]}', NULL, 'internal validity / external validity / construct validity', '[{"en":"The validity of the survey depends on the sampling method.","zh-TW":"調查的有效性取決於抽樣方法。"},{"en":"Researchers must assess both validity and reliability of their instruments.","zh-TW":"研究員必須評估其工具的有效性和可靠性。"}]', '{"adjective":"valid","adverb":"validly"}', NULL, 3, 6852, NULL),
(6853, 'valuable', '/ˈvæljuəbl/', 'adjective', '{"zh-TW":["有價值的；貴重的"],"en":["worth a great deal; very useful"]}', NULL, 'valuable experience / valuable asset / valuable feedback', '[{"en":"Your feedback is extremely valuable to us.","zh-TW":"您的回饋對我們非常有價值。"},{"en":"Experienced employees are valuable assets.","zh-TW":"有經驗的員工是寶貴的資產。"}]', '{"noun":"value","adjective":"valuable, invaluable"}', NULL, 3, 6853, NULL),
(6854, 'valuation', '/ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["估值；估價"],"en":["the process of determining the worth of something"]}', NULL, 'company valuation / property valuation', '[{"en":"The startup''s valuation reached $1 billion.","zh-TW":"這家新創公司估值達到10億美元。"},{"en":"We ordered a property valuation.","zh-TW":"我們委託了不動產估價。"}]', '{"noun":"valuation","verb":"value","verb2":"valuate"}', NULL, 3, 6854, NULL),
(6855, 'valuation method', '/ˌvæljuˈeɪʃən ˈmeθəd/', 'noun', '{"zh-TW":["估值方法"],"en":["a technique used to determine the value of a business or asset"]}', NULL, 'apply a valuation method / discounted cash flow valuation method', '[{"en":"The most common valuation method for businesses is discounted cash flow.","zh-TW":"最常見的企業估值方法是折現現金流法。"},{"en":"The valuation method affects the final price agreed in a merger.","zh-TW":"估值方法影響了合併中商定的最終價格。"}]', NULL, NULL, 5, 6855, NULL),
(6856, 'valuation multiple', '/ˌvæljuˈeɪʃən ˈmʌltɪpəl/', 'noun', '{"zh-TW":["估值倍數"],"en":["a ratio used to value a company relative to a financial metric such as earnings or revenue"]}', NULL, 'apply a valuation multiple / valuation multiple expansion / valuation multiple compression', '[{"en":"Investors pay higher valuation multiples for companies with stronger growth prospects.","zh-TW":"投資者為增長前景更強勁的公司支付更高的估值倍數。"},{"en":"Valuation multiple compression occurs when investor sentiment deteriorates.","zh-TW":"當投資者情緒惡化時，估值倍數收縮就會發生。"}]', NULL, NULL, 5, 6856, NULL),
(6857, 'valuation multiples', '/ˌvæljuˈeɪʃən ˈmʌltɪplz/', 'noun', '{"zh-TW":["估值倍數"],"en":["ratios used to estimate company value relative to earnings or assets"]}', NULL, 'apply valuation multiples / valuation multiple comparison', '[{"en":"The acquisition was priced at 15 times earnings based on industry valuation multiples.","zh-TW":"收購按行業估值倍數的15倍盈利定價。"},{"en":"Valuation multiples vary widely across different sectors.","zh-TW":"不同行業的估值倍數差異很大。"}]', NULL, NULL, 5, 6857, NULL),
(6858, 'value', '/ˈvæljuː/', 'noun, verb', '{"zh-TW":["價值；價格","重視；估價"],"en":["the importance or worth of something","to consider important"]}', NULL, 'added value / core values / market value', '[{"en":"The company''s core values include integrity and innovation.","zh-TW":"公司的核心價值包括誠信和創新。"},{"en":"We value our employees'' contributions.","zh-TW":"我們重視員工的貢獻。"}]', '{"noun":"value, valuation","verb":"value","adjective":"valuable"}', NULL, 2, 6858, 237),
(6859, 'value added', '/ˈvæljuː ˈædɪd/', 'noun', '{"zh-TW":["附加價值"],"en":["the extra value created at each stage of production or service delivery"]}', NULL, 'create value added / value added service', '[{"en":"The consulting firm provides significant value added through industry expertise.","zh-TW":"諮詢公司通過行業專業知識提供了顯著的附加價值。"},{"en":"Manufacturing processes add value added to raw materials.","zh-TW":"製造過程為原材料增加了附加價值。"}]', '{"adjective":"value-added"}', NULL, 4, 6859, NULL),
(6860, 'value chain', '/ˈvæljuː tʃeɪn/', 'noun', '{"zh-TW":["價值鏈"],"en":["the full range of activities required to create a product or service"]}', NULL, 'analyze the value chain / optimize the value chain', '[{"en":"Improving efficiency at each step of the value chain reduces costs.","zh-TW":"改善價值鏈每個步驟的效率降低了成本。"},{"en":"The company mapped its value chain to identify improvement opportunities.","zh-TW":"公司繪製了其價值鏈以識別改進機會。"}]', NULL, NULL, 4, 6860, NULL),
(6861, 'value engineering', '/ˈvæljuː ˌendʒɪˈnɪərɪŋ/', 'noun', '{"zh-TW":["價值工程"],"en":["a systematic approach to improve product functions while reducing costs"]}', NULL, 'apply value engineering / value engineering review', '[{"en":"Value engineering reduced the manufacturing cost by 18%.","zh-TW":"價值工程將製造成本降低了18%。"},{"en":"Value engineering focuses on delivering the same function at lower cost.","zh-TW":"價值工程專注於以較低的成本提供相同的功能。"}]', NULL, NULL, 5, 6861, NULL),
(6862, 'value investing', '/ˈvæljuː ɪnˈvestɪŋ/', 'noun', '{"zh-TW":["價值投資"],"en":["an investment strategy focused on finding undervalued stocks"]}', NULL, 'practice value investing / value investing principles', '[{"en":"Value investing involves buying stocks trading below their intrinsic value.","zh-TW":"價值投資涉及購買交易價格低於其內在價值的股票。"},{"en":"Warren Buffett is widely regarded as the champion of value investing.","zh-TW":"沃倫·巴菲特被廣泛視為價值投資的倡導者。"}]', NULL, NULL, 5, 6862, NULL),
(6863, 'value proposition', '/ˈvæljuː ˌprɒpəˈzɪʃən/', 'noun', '{"zh-TW":["價值主張；價值定位"],"en":["the unique benefit a company offers to its customers"]}', NULL, 'clear value proposition / value proposition statement', '[{"en":"Their value proposition focuses on speed and convenience.","zh-TW":"他們的價值主張著重於速度和便利性。"},{"en":"Defining a strong value proposition is critical for sales.","zh-TW":"定義強有力的價值主張對銷售至關重要。"}]', '{"adjective":"value-driven"}', NULL, 5, 6863, NULL),
(6864, 'value-added', '/ˈvæljuː ˈædɪd/', 'adjective', '{"zh-TW":["增值的；附加價值的"],"en":["enhanced in value through extra work or services"]}', NULL, 'value-added service / value-added tax', '[{"en":"The company differentiates itself through value-added services.","zh-TW":"公司通過增值服務使自己與眾不同。"},{"en":"Value-added tax is applied to most goods and services.","zh-TW":"增值稅適用於大多數商品和服務。"}]', NULL, NULL, 4, 6864, NULL),
(6865, 'value-added reseller', '/ˈvæljuː ˈædɪd rɪˈselər/', 'noun', '{"zh-TW":["增值經銷商"],"en":["a company that adds features or services to a product before reselling"]}', NULL, 'VAR agreement / work with value-added resellers', '[{"en":"The software firm built a network of value-added resellers.","zh-TW":"軟體公司建立了增值經銷商網路。"},{"en":"Value-added resellers provide implementation support alongside the product.","zh-TW":"增值經銷商在產品旁邊提供實施支援。"}]', '{"abbreviation":"VAR"}', NULL, 5, 6865, NULL),
(6866, 'value-added services', '/ˈvæljuː ˈædɪd ˈsɜːrvɪsɪz/', 'noun', '{"zh-TW":["增值服務"],"en":["additional services provided beyond the standard offering to enhance customer experience"]}', NULL, 'offer value-added services / value-added service package', '[{"en":"The logistics company offered value-added services like custom labeling.","zh-TW":"物流公司提供了包括定制標籤在內的增值服務。"},{"en":"Value-added services differentiate a business from low-cost competitors.","zh-TW":"增值服務使業務與低成本競爭對手區分開來。"}]', NULL, NULL, 5, 6866, NULL),
(6867, 'value-added tax', '/ˈvæljuː ˈædɪd tæks/', 'noun', '{"zh-TW":["增值稅"],"en":["a consumption tax applied at each stage of production and distribution"]}', NULL, 'charge value-added tax / value-added tax rate', '[{"en":"Businesses must register for value-added tax above a certain revenue threshold.","zh-TW":"收入超過一定門檻的企業必須登記徵收增值稅。"},{"en":"Value-added tax is a major source of government revenue.","zh-TW":"增值稅是政府收入的主要來源。"}]', '{"abbreviation":"VAT"}', NULL, 5, 6867, NULL),
(6868, 'variability', '/ˌveəriəˈbɪlɪti/', 'noun', '{"zh-TW":["變異性；可變性"],"en":["the quality of being liable to vary or change"]}', NULL, 'reduce variability / natural variability / statistical variability', '[{"en":"Climate variability makes it difficult to attribute single events to warming.","zh-TW":"氣候變異性使得難以將單個事件歸因於暖化。"},{"en":"Reducing process variability is a key goal of quality management systems.","zh-TW":"減少流程變異性是品質管理系統的關鍵目標。"}]', '{"adjective":"variable","verb":"vary"}', NULL, 4, 6868, NULL),
(6869, 'variable', '/ˈveriəbl/', 'noun, adjective', '{"zh-TW":["變數；變量","可變的"],"en":["a factor that can change","liable to change"]}', NULL, 'key variable / variable cost / variable rate', '[{"en":"Several variables affect the outcome.","zh-TW":"幾個變數影響結果。"},{"en":"Variable costs fluctuate with production volume.","zh-TW":"變動成本隨產量波動。"}]', '{"noun":"variable, variability","adjective":"variable"}', NULL, 3, 6869, 478),
(6870, 'variable cost', '/ˈvɛəriəbəl kɒst/', 'noun', '{"zh-TW":["變動成本"],"en":["a cost that changes with the level of output"]}', NULL, 'track variable costs / reduce variable costs', '[{"en":"Raw materials are a major variable cost in manufacturing.","zh-TW":"原材料是製造業的主要變動成本。"},{"en":"As production increases, variable costs rise proportionally.","zh-TW":"隨著產量增加，變動成本按比例上升。"}]', NULL, NULL, 5, 6870, NULL),
(6871, 'variable costs', '/ˈveəriəbəl kɒsts/', 'noun', '{"zh-TW":["可變成本"],"en":["costs that change in proportion to output or activity levels"]}', NULL, 'calculate variable costs / reduce variable costs / variable costs vs fixed costs', '[{"en":"Variable costs such as raw materials increase directly with production volume.","zh-TW":"原材料等可變成本直接隨生產量增加而增加。"},{"en":"Understanding variable costs is essential for accurate break-even analysis.","zh-TW":"了解可變成本對於準確的損益平衡分析至關重要。"}]', NULL, NULL, 5, 6871, NULL),
(6872, 'variable pay', '/ˈveəriəbl peɪ/', 'noun', '{"zh-TW":["績效薪酬；浮動薪酬"],"en":["compensation that varies based on performance or company results"]}', NULL, 'variable pay structure / earn variable pay / variable pay plan', '[{"en":"Variable pay aligned employee incentives with company performance.","zh-TW":"績效薪酬將員工激勵與公司績效保持一致。"},{"en":"Variable pay can make up 30% of total compensation for sales roles.","zh-TW":"銷售職位的績效薪酬可佔總薪酬的30%。"}]', NULL, NULL, 4, 6872, NULL),
(6873, 'variable rate', '/ˈveəriəbəl reɪt/', 'noun', '{"zh-TW":["浮動利率；可變利率"],"en":["an interest rate that changes over time based on market conditions"]}', NULL, 'floating variable rate / variable rate loan / switch from variable rate', '[{"en":"The mortgage has a variable rate tied to the prime lending rate.","zh-TW":"抵押貸款採用與最優惠貸款利率掛鉤的浮動利率。"},{"en":"Borrowers on variable rate loans face higher risk when rates rise.","zh-TW":"浮動利率貸款的借款人在利率上升時面臨更高的風險。"}]', NULL, NULL, 5, 6873, NULL),
(6874, 'variance analysis', '/ˈveəriəns əˈnæləsɪs/', 'noun', '{"zh-TW":["差異分析"],"en":["the study of differences between planned and actual financial results"]}', NULL, 'conduct variance analysis / explain variance', '[{"en":"Variance analysis showed that sales volumes were 10% below budget.","zh-TW":"差異分析顯示銷售量低於預算10%。"},{"en":"Monthly variance analysis helps management respond quickly to deviations.","zh-TW":"月度差異分析幫助管理層快速回應偏差。"}]', NULL, NULL, 5, 6874, NULL),
(6875, 'variation', '/ˌveriˈeɪʃn/', 'noun', '{"zh-TW":["變化；差異"],"en":["a change or difference in condition"]}', NULL, 'price variation / slight variation / seasonal variation', '[{"en":"There is considerable variation in pricing.","zh-TW":"定價有相當大的差異。"},{"en":"Seasonal variations affect tourism revenue.","zh-TW":"季節性變化影響旅遊收入。"}]', '{"noun":"variation, variety","verb":"vary","adjective":"various, varied"}', NULL, 3, 6875, NULL),
(6876, 'variety', '/vəˈraɪəti/', 'noun', '{"zh-TW":["多樣性；種類"],"en":["a range of different things"]}', NULL, 'wide variety / variety of options / add variety', '[{"en":"We offer a wide variety of products.","zh-TW":"我們提供各式各樣的產品。"},{"en":"A variety of factors contributed to the success.","zh-TW":"多種因素促成了這次的成功。"}]', '{"noun":"variety","adjective":"various, varied","verb":"vary"}', NULL, 3, 6876, NULL),
(6877, 'various', '/ˈveriəs/', 'adjective', '{"zh-TW":["各種的；不同的"],"en":["several different types of"]}', NULL, 'various reasons / various options / various departments', '[{"en":"We explored various options before deciding.","zh-TW":"我們在決定前探索了各種選項。"},{"en":"The product is available in various sizes.","zh-TW":"該產品有各種尺寸。"}]', '{"adjective":"various","noun":"variety","verb":"vary"}', NULL, 3, 6877, 238),
(6878, 'varsity', '/''vɑːrsɪti/', 'adjective', '{"zh-TW":["大學代表隊的；校隊的"],"en":["relating to the principal team representing a university, college, or school in athletic competitions"]}', NULL, 'varsity team / varsity player / varsity sport', '[{"en":"She earned a spot on the varsity swimming team in her freshman year.","zh-TW":"她在大一時贏得了校隊游泳隊的資格。"},{"en":"Varsity athletes often receive scholarships based on their athletic performance.","zh-TW":"校隊運動員通常根據他們的運動表現獲得獎學金。"}]', NULL, NULL, 3, 6878, NULL),
(6879, 'vary', '/ˈveəri/', 'verb', '{"zh-TW":["變化；不同"],"en":["to differ or change","to differ; to change"]}', '{"root":{"text":"var","meaning":"change (改變)"},"suffix":{"text":"-y","meaning":"action (動作)"},"logic":"產生改變，即「變化」。"}', 'vary from / vary widely / results may vary; vary from / vary depending on / prices vary', '[{"en":"Prices vary depending on the season.","zh-TW":"價格因季節而異。"},{"en":"Opinions on this topic vary widely.","zh-TW":"對這個話題的看法差異很大。"},{"en":"Quality can vary significantly between suppliers.","zh-TW":"不同供應商之間品質差異很大。"}]', '{"noun":"variety","noun2":"variation","adjective":"various","verb":"vary"}', NULL, 1, 6879, NULL),
(6880, 'vast', '/væst/', 'adjective', '{"zh-TW":["巨大的；廣闘的"],"en":["extremely large in area, size, or amount"]}', NULL, 'vast majority / vast amount / vast experience', '[{"en":"The vast majority of customers were satisfied.","zh-TW":"絕大多數客戶都感到滿意。"},{"en":"She has vast experience in international trade.","zh-TW":"她在國際貿易方面有豐富的經驗。"}]', '{"adjective":"vast","adverb":"vastly"}', NULL, 1, 6880, NULL),
(6881, 'VAT', '/ˌviː eɪ ˈtiː/', 'noun', '{"zh-TW":["增值稅"],"en":["value-added tax; a consumption tax applied to products at each stage of production"]}', NULL, 'pay VAT / charge VAT / VAT return / VAT registration / VAT rate', '[{"en":"All prices include VAT at the standard rate of 20%.","zh-TW":"所有價格均包含20%標準稅率的增值稅。"},{"en":"Businesses must register for VAT once turnover exceeds the threshold.","zh-TW":"一旦營業額超過門檻，企業必須登記增值稅。"}]', '{"full form":"value-added tax"}', NULL, 1, 6881, NULL),
(6882, 'vegan', '/ˈviːɡən/', 'adjective', '{"zh-TW":["純素的"],"en":["containing no animal products"]}', NULL, 'vegan menu / vegan option', '[{"en":"The restaurant now offers an extensive vegan menu.","zh-TW":"餐廳現在提供豐富的純素菜單。"},{"en":"Ask the chef for vegan alternatives to the main dishes.","zh-TW":"請詢問廚師主菜的純素替代選項。"}]', '{"noun":"vegan","noun2":"veganism"}', NULL, 2, 6882, NULL),
(6883, 'veganism', '/''viːɡənɪzəm/', 'noun', '{"zh-TW":["純素食主義；素食主義"],"en":["the practice of abstaining from the use of animal products, especially in diet"]}', NULL, 'practice veganism / adopt veganism / switch to veganism', '[{"en":"She adopted veganism for environmental and ethical reasons.","zh-TW":"她出於環境和道德原因採用了純素食主義。"},{"en":"The restaurant expanded its menu to cater for the growing interest in veganism.","zh-TW":"餐廳擴展了菜單，以迎合對純素食主義日益增長的興趣。"}]', '{"adjective":"vegan","noun":"vegan"}', NULL, 3, 6883, NULL),
(6884, 'vegetable', '/ˈvɛdʒtəbəl/', 'noun', '{"zh-TW":["蔬菜"],"en":["a plant or part of a plant eaten as food"]}', NULL, 'fresh vegetable / seasonal vegetable', '[{"en":"The menu highlights seasonal vegetables from local farms.","zh-TW":"菜單強調來自當地農場的季節性蔬菜。"},{"en":"Add more vegetables to your diet for better health.","zh-TW":"多吃蔬菜有益健康。"}]', '{"adjective":"vegetable"}', NULL, 3, 6884, NULL),
(6885, 'vegetarian', '/ˌvɛdʒɪˈtɛəriən/', 'adjective', '{"zh-TW":["素食的"],"en":["not containing meat or fish"]}', NULL, 'vegetarian dish / vegetarian option', '[{"en":"We need a vegetarian option for one of our guests.","zh-TW":"我們需要為其中一位客人提供素食選項。"},{"en":"The restaurant has a dedicated vegetarian menu.","zh-TW":"餐廳有專門的素食菜單。"}]', '{"noun":"vegetarian","noun2":"vegetarianism"}', NULL, 4, 6885, NULL),
(6886, 'vegetarian diet', '/''vedʒɪˌteəriən ˌdaɪɪt/', 'noun', '{"zh-TW":["素食飲食；蔬食"],"en":["a diet that excludes meat, fish, and seafood but may include dairy products and eggs"]}', NULL, 'follow a vegetarian diet / switch to a vegetarian diet / benefits of vegetarian diet', '[{"en":"A well-planned vegetarian diet can provide all essential nutrients.","zh-TW":"精心規劃的素食飲食可以提供所有必需的營養素。"},{"en":"Many athletes follow a vegetarian diet while maintaining high performance levels.","zh-TW":"許多運動員在保持高水平表現的同時遵循素食飲食。"}]', '{"adjective":"vegetarian","noun":"vegetarian"}', NULL, 5, 6886, NULL),
(6887, 'vehicle', '/ˈviːɪkl/', 'noun', '{"zh-TW":["車輛；交通工具","媒介；手段"],"en":["a means of transport","a means of expressing ideas"]}', NULL, 'electric vehicle / company vehicle / investment vehicle', '[{"en":"Electric vehicles are gaining market share.","zh-TW":"電動車正在獲得市場佔有率。"},{"en":"The newsletter is a vehicle for company announcements.","zh-TW":"電子報是公司公告的媒介。"}]', '{"noun":"vehicle","adjective":"vehicular"}', NULL, 3, 6887, NULL),
(6888, 'velocity', '/vɪˈlɒsɪti/', 'noun', '{"zh-TW":["速度；開發速率"],"en":["in agile, the amount of work a team can complete in a sprint"]}', NULL, 'team velocity / measure velocity / average velocity / increase velocity', '[{"en":"The team''s velocity increased after removing process bottlenecks.","zh-TW":"消除流程瓶頸後，團隊的開發速率提高了。"},{"en":"Velocity is measured in story points completed per sprint.","zh-TW":"速度以每個衝刺完成的故事點數衡量。"}]', '{"plural":"velocities"}', NULL, 3, 6888, NULL),
(6889, 'velocity of money', '/vɪˈlɒsɪti əv ˈmʌni/', 'noun', '{"zh-TW":["貨幣流通速度"],"en":["the frequency at which money changes hands in an economy within a given period"]}', NULL, 'increase velocity of money / declining velocity of money / measure velocity of money', '[{"en":"A higher velocity of money indicates that each unit of currency is being used more frequently.","zh-TW":"較高的貨幣流通速度表明每單位貨幣的使用頻率更高。"},{"en":"Quantitative easing increased the money supply but did not increase the velocity of money.","zh-TW":"量化寬鬆增加了貨幣供應量，但沒有增加貨幣流通速度。"}]', NULL, NULL, 5, 6889, NULL),
(6890, 'vendor', '/ˈvendər/', 'noun', '{"zh-TW":["供應商；賣方"],"en":["a person or company that sells goods"]}', NULL, 'vendor management / preferred vendor / third-party vendor', '[{"en":"We are evaluating new vendors for the contract.","zh-TW":"我們正在評估新的供應商。"},{"en":"The vendor delivered the goods on time.","zh-TW":"供應商準時交付了貨物。"}]', '{"noun":"vendor"}', NULL, 2, 6890, 239),
(6891, 'vendor due diligence', '/ˈvendər djuː ˈdɪlɪdʒəns/', 'noun', '{"zh-TW":["供應商盡職調查"],"en":["an investigation conducted by the seller to prepare for buyer questions in a transaction"]}', NULL, 'conduct vendor due diligence / vendor due diligence report', '[{"en":"The seller prepared a vendor due diligence report before listing the company.","zh-TW":"賣方在出售公司前準備了供應商盡職調查報告。"},{"en":"Vendor due diligence speeds up the sale process by providing ready information.","zh-TW":"供應商盡職調查通過提供現成信息加快了銷售流程。"}]', NULL, NULL, 5, 6891, NULL),
(6892, 'vendor financing', '/ˈvendər ˈfaɪnænsɪŋ/', 'phrase', '{"zh-TW":["賣方融資"],"en":["a loan extended by a seller to a buyer to facilitate a transaction"]}', NULL, 'provide vendor financing / accept vendor financing / vendor financing deal', '[{"en":"The seller offered vendor financing to close the deal quickly.","zh-TW":"賣方提供賣方融資以迅速完成交易。"},{"en":"Vendor financing is common in small business acquisitions.","zh-TW":"賣方融資在小型企業收購中很常見。"}]', NULL, NULL, 5, 6892, NULL),
(6893, 'vendor management', '/ˈvendər ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["供應商管理"],"en":["the process of managing vendor relationships, contracts, and performance"]}', NULL, 'vendor management system / vendor management process / strategic vendor management', '[{"en":"Effective vendor management ensures consistent product quality.","zh-TW":"有效的供應商管理確保一致的產品品質。"},{"en":"The procurement team handles all vendor management activities.","zh-TW":"採購團隊處理所有供應商管理活動。"}]', '{"noun":"vendor manager"}', NULL, 5, 6893, NULL),
(6894, 'vendor selection', '/ˈvendər sɪˈlekʃən/', 'noun', '{"zh-TW":["供應商選擇"],"en":["the process of evaluating and choosing a supplier for goods or services"]}', NULL, 'manage vendor selection / vendor selection criteria', '[{"en":"The vendor selection process included price, quality, and delivery evaluation.","zh-TW":"供應商選擇流程包括價格、品質和交貨評估。"},{"en":"A formal vendor selection process reduces procurement risk.","zh-TW":"正式的供應商選擇流程降低了採購風險。"}]', NULL, NULL, 5, 6894, NULL),
(6895, 'ventilator', '/ˈventɪleɪtər/', 'noun', '{"zh-TW":["呼吸器；人工呼吸機"],"en":["a machine that supports breathing in patients who cannot breathe independently"]}', NULL, 'put on a ventilator / ventilator support / wean off a ventilator', '[{"en":"The critically ill patient was placed on a ventilator in the ICU.","zh-TW":"重症患者在加護病房被置於呼吸器上。"},{"en":"Weaning patients from ventilators is a gradual and careful process.","zh-TW":"讓患者脫離呼吸器是一個漸進而謹慎的過程。"}]', NULL, NULL, 4, 6895, NULL),
(6896, 'venture', '/ˈventʃər/', 'noun, verb', '{"zh-TW":["企業；冒險事業","冒險；敢於"],"en":["a risky business enterprise","to dare to do something risky"]}', NULL, 'joint venture / venture capital / new venture', '[{"en":"They launched a joint venture with a local partner.","zh-TW":"他們與當地合作夥伴成立了合資企業。"},{"en":"Venture capital funded the startup''s growth.","zh-TW":"風險投資資助了新創公司的成長。"}]', '{"noun":"venture, venturer","verb":"venture"}', NULL, 3, 6896, 726),
(6897, 'venture capital', '/ˈventʃər ˈkæpɪtl/', 'noun', '{"zh-TW":["創業投資；風險投資"],"en":["financing provided to early-stage startups with growth potential"]}', NULL, 'venture capital firm / venture capital funding / raise venture capital', '[{"en":"The startup secured $5 million in venture capital.","zh-TW":"這家新創公司獲得了500萬美元的創業投資。"},{"en":"Venture capital investors often take a board seat.","zh-TW":"創業投資者通常獲得董事會席位。"}]', '{"abbreviation":"VC","noun":"venture capitalist"}', NULL, 5, 6897, NULL),
(6898, 'venue', '/ˈvɛnjuː/', 'noun', '{"zh-TW":["場地；地點"],"en":["the place where an event happens","a place where an event is held"]}', NULL, 'concert venue / change of venue; event venue / conference venue / change of venue', '[{"en":"The wedding venue is beautiful.","zh-TW":"婚禮場地很漂亮。"},{"en":"What''s the venue for the conference?","zh-TW":"會議的場地在哪裡？"},{"en":"The conference venue holds 500 attendees.","zh-TW":"會議場地可容納500位出席者。"},{"en":"We need to book a venue for the annual gala.","zh-TW":"我們需要為年度晚宴預訂場地。"}]', '{"noun":"venue"}', NULL, 2, 6898, NULL),
(6899, 'venue booking', '/ˈvɛnjuː ˈbʊkɪŋ/', 'noun', '{"zh-TW":["場地預訂"],"en":["reserving a location for an event"]}', NULL, 'confirm a venue booking / venue booking policy', '[{"en":"Venue booking should be done at least three months in advance.","zh-TW":"場地預訂應至少提前三個月進行。"},{"en":"The venue booking confirmation was sent by email.","zh-TW":"場地預訂確認已透過電子郵件發送。"}]', NULL, NULL, 5, 6899, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6900, 'verbal agreement', '/ˈvɜːrbəl əˈɡriːmənt/', 'noun', '{"zh-TW":["口頭協議"],"en":["a contract agreed upon through spoken words without written documentation"]}', NULL, 'rely on a verbal agreement / document a verbal agreement', '[{"en":"Although a verbal agreement was reached, a formal contract was still needed.","zh-TW":"雖然達成了口頭協議，但仍需要正式合約。"},{"en":"A verbal agreement may be enforceable but is difficult to prove.","zh-TW":"口頭協議可能具有可執行性，但難以證明。"}]', NULL, NULL, 5, 6900, NULL),
(6901, 'verbal communication', '/''vɜːrbəl kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["口頭溝通；言語交流"],"en":["the transmission of information using spoken words"]}', NULL, 'effective verbal communication / verbal communication skills / practice verbal communication', '[{"en":"Strong verbal communication skills are essential for customer-facing roles.","zh-TW":"強大的口頭溝通技能對於面向客戶的職位至關重要。"},{"en":"Clear verbal communication prevents misunderstandings in a team environment.","zh-TW":"清晰的口頭溝通可以防止團隊環境中的誤解。"}]', NULL, NULL, 5, 6901, NULL),
(6902, 'verbal cue', '/''vɜːrbəl kjuː/', 'noun', '{"zh-TW":["語言線索；口頭提示"],"en":["a spoken signal or hint that helps another person understand what to do or what is meant"]}', NULL, 'pick up on verbal cues / use verbal cues / respond to verbal cues', '[{"en":"A good interviewer listens carefully for verbal cues that reveal a candidate''s character.","zh-TW":"一位出色的面試官會仔細聆聽揭示候選人性格的語言線索。"},{"en":"Teachers use verbal cues to guide students through difficult concepts.","zh-TW":"教師使用口頭提示引導學生理解困難的概念。"}]', NULL, NULL, 4, 6902, NULL),
(6903, 'verbatim', '/vɜːrˈbeɪtɪm/', 'adverb', '{"zh-TW":["逐字地；原文照錄"],"en":["in exactly the same words as were used originally"]}', NULL, 'verbatim record / transcribe verbatim / verbatim quote', '[{"en":"The secretary recorded the CEO''s statement verbatim.","zh-TW":"秘書逐字記錄了執行長的聲明。"},{"en":"The contract was copied verbatim into the proposal document.","zh-TW":"合約被原文照錄到提案文件中。"}]', '{"adjective":"verbatim"}', NULL, 3, 6903, NULL),
(6904, 'verbose', '/''vɜːrˈbəʊs/', 'adjective', '{"zh-TW":["囉嗦的；冗長的"],"en":["using more words than are needed; wordy"]}', NULL, 'verbose report / verbose writing / avoid being verbose', '[{"en":"The verbose email could have been summarized in three sentences.","zh-TW":"這封冗長的電子郵件本可以用三句話概括。"},{"en":"His verbose writing style made documents difficult to read quickly.","zh-TW":"他囉嗦的寫作風格使文件難以快速閱讀。"}]', '{"adverb":"verbosely","noun":"verbosity"}', NULL, 3, 6904, NULL),
(6905, 'verdict', '/ˈvɜːrdɪkt/', 'noun', '{"zh-TW":["裁決；判決"],"en":["the decision made by a jury"]}', NULL, 'guilty verdict / reach a verdict', '[{"en":"The jury reached a verdict of not guilty.","zh-TW":"陪審團做出了無罪裁決。"},{"en":"The verdict was announced in court.","zh-TW":"裁決在法庭上宣布。"}]', NULL, NULL, 3, 6905, NULL),
(6906, 'verify', '/ˈverɪfaɪ/', 'verb', '{"zh-TW":["驗證；核實"],"en":["to confirm the truth or accuracy of"]}', '{"root":{"text":"ver","meaning":"true (真實)"},"suffix":{"text":"-ify","meaning":"使..."}}', 'verify information / verify identity / verify data', '[{"en":"Please verify the information before submitting.","zh-TW":"提交前請驗證資訊。"},{"en":"We need to verify the customer''s identity.","zh-TW":"我們需要核實客戶的身分。"}]', '{"noun":"verification","verb":"verify","adjective":"verifiable"}', NULL, 2, 6906, 67),
(6907, 'vernacular', '/vəˈnækjʊlər/', 'noun', '{"zh-TW":["方言；本地語言；行話"],"en":["the language or dialect spoken by the ordinary people of a region"]}', NULL, 'local vernacular / technical vernacular / vernacular speech', '[{"en":"The document was written in the legal vernacular of the jurisdiction.","zh-TW":"該文件以該司法管轄區的法律行話撰寫。"},{"en":"Understanding the vernacular of a field helps communication.","zh-TW":"理解一個領域的行話有助於溝通。"}]', NULL, NULL, 4, 6907, NULL),
(6908, 'vernissage', '/vɜːnɪˈsɑːʒ/', 'noun', '{"zh-TW":["展覽開幕式；開幕預覽"],"en":["the opening event of an art exhibition, usually by private invitation"]}', NULL, 'attend a vernissage / gallery vernissage / exclusive vernissage', '[{"en":"Artists and collectors gathered at the gallery vernissage to view the new works.","zh-TW":"藝術家和收藏家聚集在畫廊開幕式上欣賞新作品。"},{"en":"The vernissage included a reception with the artist in residence.","zh-TW":"開幕式包括一個與駐場藝術家的接待會。"}]', NULL, NULL, 4, 6908, NULL),
(6909, 'versatile', '/ˈvɜːrsətl/', 'adjective', '{"zh-TW":["多功能的；多才多藝的"],"en":["able to adapt to many functions"]}', NULL, 'versatile tool / versatile employee / highly versatile', '[{"en":"The software is versatile enough for various tasks.","zh-TW":"這個軟體功能多樣，適用於各種任務。"},{"en":"She is a versatile team member.","zh-TW":"她是一位多才多藝的團隊成員。"}]', '{"noun":"versatility","adjective":"versatile"}', NULL, 3, 6909, NULL),
(6910, 'version', '/ˈvɜːrʒn/', 'noun', '{"zh-TW":["版本"],"en":["a particular form of something"]}', NULL, 'latest version / updated version / previous version', '[{"en":"Download the latest version of the app.","zh-TW":"下載應用程式的最新版本。"},{"en":"This is the final version of the report.","zh-TW":"這是報告的最終版本。"}]', '{"noun":"version"}', NULL, 3, 6910, 240),
(6911, 'version control', '/ˈvɜːrʒən kənˈtrəʊl/', 'noun', '{"zh-TW":["版本控制"],"en":["a system that tracks changes to files over time"]}', NULL, 'use version control / version control system / distributed version control', '[{"en":"Git is the most widely used version control system in software development.","zh-TW":"Git是軟件開發中使用最廣泛的版本控制系統。"},{"en":"Version control makes it easy to revert to an earlier state of the codebase.","zh-TW":"版本控制使回滾到代碼庫的早期狀態變得容易。"}]', '{"verb":"version-control"}', NULL, 5, 6911, NULL),
(6912, 'vertical integration', '/ˈvɜːrtɪkəl ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["垂直整合"],"en":["a strategy where a company controls multiple stages of its supply chain"]}', NULL, 'pursue vertical integration / benefits of vertical integration', '[{"en":"The manufacturer achieved vertical integration by acquiring its supplier.","zh-TW":"製造商通過收購其供應商實現了垂直整合。"},{"en":"Vertical integration reduces dependence on third-party suppliers.","zh-TW":"垂直整合降低了對第三方供應商的依賴。"}]', '{"opposite":"horizontal integration"}', NULL, 5, 6912, NULL),
(6913, 'vertical market', '/ˈvɜːrtɪkəl ˈmɑːrkɪt/', 'noun', '{"zh-TW":["垂直市場"],"en":["a market comprising businesses in a specific industry"]}', NULL, 'target a vertical market / vertical market strategy', '[{"en":"The startup focuses on the healthcare vertical market.","zh-TW":"這家初創公司專注於醫療垂直市場。"},{"en":"Specializing in a vertical market builds deeper expertise.","zh-TW":"專注於垂直市場可以建立更深的專業知識。"}]', NULL, NULL, 5, 6913, NULL),
(6914, 'vertically integrated', '/ˈvɜːrtɪkli ˈɪntɪɡreɪtɪd/', 'adjective', '{"zh-TW":["垂直整合的"],"en":["controlling multiple stages of production within the same company"]}', NULL, 'become vertically integrated / vertically integrated company', '[{"en":"The vertically integrated company controls raw materials to retail.","zh-TW":"垂直整合的公司控制著從原材料到零售的全過程。"},{"en":"Vertical integration gives the firm better control over quality and costs.","zh-TW":"垂直整合使公司對品質和成本有更好的控制。"}]', '{"verb":"vertically integrate","noun":"vertical integration"}', NULL, 5, 6914, NULL),
(6915, 'vessel', '/''vesəl/', 'noun', '{"zh-TW":["船隻；輪船"],"en":["a large boat or ship; also a hollow container for liquids"]}', NULL, 'cargo vessel / large vessel / vessel tracking', '[{"en":"The cargo vessel arrived at the port three days ahead of schedule.","zh-TW":"這艘貨船比計劃提前三天抵達港口。"},{"en":"The vessel''s capacity was too small to accommodate the entire shipment.","zh-TW":"這艘船的容量太小，無法裝載整批貨物。"}]', NULL, NULL, 2, 6915, NULL),
(6916, 'vested interest', '/ˈvestɪd ˈɪntrɪst/', 'noun', '{"zh-TW":["既得利益"],"en":["a personal stake or benefit in an outcome that may influence objectivity"]}', NULL, 'declare a vested interest / conflict from vested interest', '[{"en":"Board members with a vested interest in the transaction must recuse themselves.","zh-TW":"在交易中有既得利益的董事會成員必須回避。"},{"en":"A vested interest can compromise independent decision-making.","zh-TW":"既得利益可能損害獨立的決策。"}]', NULL, NULL, 5, 6916, NULL),
(6917, 'vesting', '/ˈvestɪŋ/', 'noun', '{"zh-TW":["歸屬；股權歸屬"],"en":["the process by which an employee earns full rights to employer-provided benefits over time"]}', NULL, 'vesting schedule / vesting period / cliff vesting', '[{"en":"The options follow a four-year vesting schedule with a one-year cliff.","zh-TW":"期權遵循四年歸屬計畫，有一年懸崖期。"},{"en":"Vesting ensures employees remain motivated over the long term.","zh-TW":"歸屬確保員工長期保持積極性。"}]', '{"verb":"vest","adjective":"vested"}', NULL, 3, 6917, NULL),
(6918, 'vesting period', '/ˈvestɪŋ ˈpɪəriəd/', 'noun', '{"zh-TW":["歸屬期；兌現期"],"en":["the time an employee must wait before gaining full ownership of awarded shares or benefits"]}', NULL, 'complete the vesting period / vesting period schedule', '[{"en":"Employees must complete a three-year vesting period before claiming shares.","zh-TW":"員工必須完成三年歸屬期才能申領股份。"},{"en":"A longer vesting period encourages employee retention.","zh-TW":"較長的歸屬期鼓勵了員工留任。"}]', NULL, NULL, 5, 6918, NULL),
(6919, 'vesting schedule', '/ˈvestɪŋ ˈʃedjuːl/', 'noun', '{"zh-TW":["歸屬計劃；股權解鎖時間表"],"en":["a timeline determining when an employee earns the right to equity or benefits"]}', NULL, 'four-year vesting schedule / cliff vesting / accelerated vesting', '[{"en":"The stock options vest over a four-year vesting schedule.","zh-TW":"股票選擇權按照四年歸屬計劃解鎖。"},{"en":"He left before his options fully vested under the vesting schedule.","zh-TW":"他在股票選擇權按歸屬計劃完全解鎖前離職了。"}]', NULL, NULL, 5, 6919, NULL),
(6920, 'veto', '/ˈviːtoʊ/', 'noun, verb', '{"zh-TW":["否決權；否決","否決"],"en":["the power to reject a decision","to reject or prohibit"]}', NULL, 'exercise a veto / veto power / veto a proposal', '[{"en":"The president vetoed the proposed legislation.","zh-TW":"總統否決了擬議的法案。"},{"en":"Shareholders have veto power over major decisions.","zh-TW":"股東對重大決策擁有否決權。"}]', '{"noun":"veto","verb":"veto"}', NULL, 1, 6920, NULL),
(6921, 'vetting', '/ˈvɛtɪŋ/', 'noun', '{"zh-TW":["審查；背景調查"],"en":["making a careful check of someone or something"]}', NULL, 'vetting process / thorough vetting', '[{"en":"All job candidates undergo a vetting process.","zh-TW":"所有求職候選人都要經過審查流程。"},{"en":"Suppliers are subject to a vetting process before approval.","zh-TW":"供應商在批准前需經過審查流程。"}]', '{"verb":"vet","adjective":"vetted"}', NULL, 3, 6921, NULL),
(6922, 'via', '/ˈvaɪə/', 'preposition', '{"zh-TW":["經由；透過"],"en":["traveling through; by means of"]}', NULL, 'via email / via telephone / via satellite', '[{"en":"Please confirm via email.","zh-TW":"請透過電子郵件確認。"},{"en":"The goods will be shipped via air freight.","zh-TW":"貨物將透過空運運送。"}]', NULL, NULL, 1, 6922, NULL),
(6923, 'viability', '/ˌvaɪəˈbɪlɪti/', 'noun', '{"zh-TW":["可行性；存活能力"],"en":["the ability of a plan, business, or idea to work or succeed"]}', NULL, 'assess viability / financial viability / commercial viability', '[{"en":"The business plan was reviewed for long-term financial viability.","zh-TW":"商業計劃的長期財務可行性進行了審查。"},{"en":"Commercial viability depends on whether the market will pay for the product.","zh-TW":"商業可行性取決於市場是否願意為該產品付費。"}]', '{"adjective":"viable","adverb":"viably"}', NULL, 3, 6923, 948),
(6924, 'viable', '/ˈvaɪəbl/', 'adjective', '{"zh-TW":["可行的；能存活的"],"en":["capable of working successfully"]}', NULL, 'commercially viable / viable option / viable alternative', '[{"en":"Is this a commercially viable product?","zh-TW":"這是一個在商業上可行的產品嗎？"},{"en":"We need to find a viable alternative.","zh-TW":"我們需要找到一個可行的替代方案。"}]', '{"noun":"viability","adjective":"viable"}', NULL, 2, 6924, NULL),
