(6926, 'vice president', '/vaɪs ˈprezɪdənt/', 'noun', '{"zh-TW":["副總裁；副會長"],"en":["a senior executive ranking just below the president in an organization"]}', NULL, 'promoted to vice president / vice president of sales', '[{"en":"She was promoted to vice president of marketing after three years.","zh-TW":"她三年後晉升為行銷副總裁。"},{"en":"The vice president presented the strategic plan to the board.","zh-TW":"副總裁向董事會提交了戰略計劃。"}]', '{"abbreviation":"VP"}', NULL, 5, 6926, NULL),
(6927, 'video conference', '/ˈvɪdioʊ ˈkɒnfərəns/', 'noun', '{"zh-TW":["視訊會議"],"en":["a meeting conducted over the internet using video and audio technology"]}', NULL, 'host a video conference / video conference platform / video conference call', '[{"en":"The international team held a video conference every Monday morning.","zh-TW":"國際團隊每週一早上舉行視訊會議。"},{"en":"Video conferencing tools became essential during remote work.","zh-TW":"視訊會議工具在遠端工作期間變得至關重要。"}]', '{"verb":"video conference"}', NULL, 5, 6927, NULL),
(6928, 'view', '/vjuː/', 'noun, verb', '{"zh-TW":["觀點；看法","認為；看待"],"en":["an opinion or way of thinking","to regard in a particular way"]}', NULL, 'point of view / in view of / view as', '[{"en":"In view of the circumstances, we postponed the launch.","zh-TW":"鑑於情況，我們延後了發布。"},{"en":"Management views this as a positive development.","zh-TW":"管理層視此為正面的發展。"}]', '{"noun":"view, viewer, viewpoint","verb":"view, review"}', NULL, 1, 6928, NULL),
