(6930, 'villa', '/''vɪlə/', 'noun', '{"zh-TW":["別墅；度假屋"],"en":["a large comfortable house, especially in a Mediterranean country or for holiday rental"]}', NULL, 'luxury villa / rent a villa / private villa', '[{"en":"The villa had its own swimming pool overlooking the sea.","zh-TW":"這棟別墅有自己的游泳池，俯瞰大海。"},{"en":"A week in a Tuscan villa is her idea of the perfect vacation.","zh-TW":"在托斯卡尼別墅度過一週是她對完美假期的設想。"}]', NULL, NULL, 2, 6930, NULL),
(6931, 'vinaigrette', '/''vɪnɪˈɡret/', 'noun', '{"zh-TW":["油醋汁；法式沙拉醬"],"en":["a salad dressing made from oil and vinegar, often with herbs, garlic, or mustard"]}', NULL, 'drizzle with vinaigrette / homemade vinaigrette / light vinaigrette', '[{"en":"She drizzled a lemon vinaigrette over the arugula salad.","zh-TW":"她在芝麻菜沙拉上淋上了檸檬油醋汁。"},{"en":"A basic vinaigrette requires just olive oil, red wine vinegar, and salt.","zh-TW":"基本的油醋汁只需要橄欖油、紅葡萄酒醋和鹽。"}]', NULL, NULL, 4, 6931, NULL),
