(6933, 'viral marketing', '/ˈvaɪrəl ˈmɑːrkɪtɪŋ/', 'noun', '{"zh-TW":["病毒式行銷"],"en":["marketing that spreads rapidly through sharing"]}', NULL, 'create viral content / viral marketing campaign', '[{"en":"The video became a viral marketing success overnight.","zh-TW":"這段影片在一夜之間成為病毒式行銷的成功案例。"},{"en":"Viral marketing can reach millions without a large budget.","zh-TW":"病毒式行銷無需大預算即可觸達數百萬人。"}]', NULL, NULL, 5, 6933, NULL),
(6934, 'virtual', '/ˈvɜːrtʃuəl/', 'adjective', '{"zh-TW":["虛擬的","虛擬的；實質上的"],"en":["created by computer; almost complete","existing in digital form; nearly as described"]}', NULL, 'virtual reality / virtual meeting; virtual meeting / virtual reality / virtual office', '[{"en":"We had a virtual meeting today.","zh-TW":"我們今天開了一場線上會議。"},{"en":"Virtual reality is becoming more popular.","zh-TW":"虛擬實境越來越受歡迎。"},{"en":"The team holds virtual meetings every Monday.","zh-TW":"團隊每週一舉行視訊會議。"},{"en":"Virtual reality is transforming training programs.","zh-TW":"虛擬實境正在改變培訓計畫。"}]', '{"adverb":"virtually","adjective":"virtual"}', NULL, 3, 6934, NULL),
