(6936, 'virtual machine', '/ˈvɜːrtʃuəl məˈʃiːn/', 'noun', '{"zh-TW":["虛擬機器"],"en":["a software emulation of a physical computer"]}', NULL, 'run on a virtual machine / create a virtual machine / virtual machine image', '[{"en":"The application runs inside a virtual machine for isolation and portability.","zh-TW":"應用程式在虛擬機器中運行以實現隔離和可移植性。"},{"en":"Virtual machines allow multiple operating systems to run on one server.","zh-TW":"虛擬機器允許多個作業系統在一台伺服器上運行。"}]', NULL, NULL, 5, 6936, NULL),
(6937, 'virtual meeting', '/ˈvɜːrtʃuəl ˈmiːtɪŋ/', 'noun', '{"zh-TW":["線上會議；虛擬會議"],"en":["a meeting conducted over the internet"]}', NULL, 'join a virtual meeting / host a virtual meeting', '[{"en":"Virtual meetings have replaced many in-person gatherings.","zh-TW":"線上會議已取代了許多面對面聚會。"},{"en":"She joined the virtual meeting from her home office.","zh-TW":"她從家庭辦公室加入了線上會議。"}]', NULL, NULL, 5, 6937, NULL),
