(6939, 'virtue', '/ˈvɜːrtʃuː/', 'noun', '{"zh-TW":["美德；優點"],"en":["moral excellence; an advantage"]}', NULL, 'by virtue of / virtue of patience / corporate virtue', '[{"en":"By virtue of her experience, she was promoted.","zh-TW":"憑藉她的經驗，她獲得了升遷。"},{"en":"Patience is a virtue in negotiations.","zh-TW":"在談判中耐心是一種美德。"}]', '{"noun":"virtue","adjective":"virtuous"}', NULL, 2, 6939, NULL),
