(6941, 'visa', '/ˈviːzə/', 'noun', '{"zh-TW":["簽證"],"en":["an official endorsement on a passport allowing entry to a country"]}', NULL, 'obtain a visa / visa application', '[{"en":"You need a valid visa to enter the country.","zh-TW":"您需要有效簽證才能入境該國。"},{"en":"The visa application process can take several weeks.","zh-TW":"簽證申請過程可能需要幾個星期。"}]', NULL, NULL, 1, 6941, NULL),
