(6945, 'vision', '/ˈvɪʒn/', 'noun', '{"zh-TW":["願景；眼光","視力"],"en":["an idea of what the future could be","the ability to see"]}', NULL, 'company vision / long-term vision / share a vision', '[{"en":"The CEO shared her vision for the company''s future.","zh-TW":"執行長分享了她對公司未來的願景。"},{"en":"A clear vision helps align team efforts.","zh-TW":"清晰的願景有助於統一團隊的努力方向。"}]', '{"noun":"vision, visionary","adjective":"visionary"}', NULL, 2, 6945, NULL),
(6946, 'vision care', '/ˈvɪʒən kɛər/', 'noun', '{"zh-TW":["視力保健；眼科護理"],"en":["healthcare services related to the eyes and vision"]}', NULL, 'vision care coverage / vision care benefits', '[{"en":"Annual eye exams are included in the vision care plan.","zh-TW":"年度眼科檢查包含在視力保健計劃中。"},{"en":"Vision care benefits cover glasses and contact lenses.","zh-TW":"視力保健福利涵蓋眼鏡和隱形眼鏡。"}]', NULL, NULL, 4, 6946, NULL),
